class Cascade(Flowable):
 def __init__(self):
  super().__init__(); self.width=499; self.height=135
 def draw(self):
  c=self.canv
  for i,(a,b,d) in enumerate([('calc','Факты и словарь','Точный ответ программы'),('decision','Известная ситуация','Ответ по правилу'),('llm','Свободный вопрос','GigaChat + справочные блоки')]):
   x=i*174;c.setFillColor(HexColor('#EDF2F8'));c.roundRect(x,40,151,75,8,fill=1,stroke=0);c.setFillColor(blue);c.setFont('InterBold',13);c.drawString(x+10,94,a);c.setFont('Inter',8);c.drawString(x+10,76,b);c.drawString(x+10,60,d)
   if i<2:
    c.setStrokeColor(blue);c.line(x+154,78,x+170,78);c.line(x+167,81,x+170,78);c.line(x+167,75,x+170,78)
  c.setFont('Inter',8);c.setFillColor(muted);c.drawString(0,20,'Слева направо: следующий уровень нужен, только если предыдущий не дал ответа.')
story=[];md=[]
def p(s,style='body'):return Paragraph(escape(s).replace('\n','<br/>'),styles[style])
def text(s,style='body'):story.append(p(s,style));md.append(s+'\n')
def page(title,first=False):
 if story:story.append(PageBreak())
 text(title,'title' if first else 'h');md[-1]=('# ' if first else '## ')+title+'\n'
def table(head,rows,widths):
 data=[[p(s,'th') for s in head]]+[[p(str(s),'cell') for s in r] for r in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),blue),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('ROWBACKGROUNDS',(0,1),(-1,-1),[white,HexColor('#F1F4F8')]),('LINEBELOW',(0,-1),(-1,-1),.5,HexColor('#DCE1EA'))]));story.append(t);story.append(Spacer(1,10))
 md.extend(['| '+' | '.join(head)+' |','| '+' | '.join(['---']*len(head))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows]+[''])
def picture(name,width=499,maxheight=480,caption=''):
 path=R/'docs/screenshots'/name; iw,ih=ImageReader(str(path)).getSize();f=min(width/iw,maxheight/ih);story.append(Image(str(path),iw*f,ih*f,hAlign='LEFT'))
 if caption:text(caption,'small')
 md.append(f'![{caption}](screenshots/{name})\n')
def gallery(items):
 cells=[]
 for name,caption in items:
  path=R/'docs/screenshots'/name;iw,ih=ImageReader(str(path)).getSize();f=min(230/iw,238/ih)
  cells.append([Image(str(path),iw*f,ih*f),Spacer(1,5),p(caption,'small')]);md.append(f'![{caption}](screenshots/{name})\n')
 t=Table([cells[:2],cells[2:]],colWidths=[249,250]);t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),14)]));story.append(t)
